void feed_watchdog(void)
{
    if ((WWDG->CR & 0x7F) < (WWDG->CFR & 0x7F))
    {
        WWDG->CR = 0x7F;
    }
}

/// INFERENCE

void relu(float* x, const uint8_t& h, const uint8_t& w, const uint8_t& c) {
  for (int k = 0; k < c; ++k) {
    for (int i = 0; i < w; ++i) {
      for (int j = 0; j < h; ++j) {
        float& value = x[k * (w * h) + i * h + j];
        if (value < 0.f)
          value = 0.f;
      }
    }
  }
}
  
void sigmoid(float* x, const uint8_t& h, const uint8_t& w, const uint8_t& c) {
  for (int k = 0; k < c; ++k) {
    for (int i = 0; i < w; ++i) {
      for (int j = 0; j < h; ++j) {
        float& value = x[k * (w * h) + i * h + j];
        value = (1.f / (1.f + expf(-value)));
      }
    }
  }
} 

void dense(const float* w, const float* b,
           const float* x, float* o,
           const uint8_t& n, const uint8_t& m, const uint8_t& p,
           float* membuf) {
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < p; ++j) {
      membuf[0] = 0.f;

      for (int k = 0; k < m; ++k) {
        membuf[0] += w[k * p + j] * x[i * m + k];
      }

      o[i * p + j] = membuf[0];
    }
  }

  // add bias
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < p; ++j) {
      o[i * p + j] += b[j];
    }
  }
}

void inference(const float* input, float* output) {
  float membuf[1] = {};
  float dense1_output[64] = {};

  dense(dense1_weight, dense1_bias, input, dense1_output, 1, 196, 64, membuf);
//  feed_watchdog();
  relu(dense1_output, 64, 1, 1);
//  feed_watchdog();
  dense(dense2_weight, dense2_bias, dense1_output, output, 1, 64, 1, membuf);
//  feed_watchdog();
  sigmoid(output, 1, 1, 1);
//  feed_watchdog();
}

